def count_nums(arr):
    def sum_of_digits(x):
        total = 0
        negative = x < 0
        x = abs(x)
        while x > 0:
            total += x % 10
            x //= 10
        return total if not negative else -total

    count = 0
    for number in arr:
        if sum_of_digits(number) > 0:
            count += 1
    return count

